input.command:
echo "== binary on PATH? =="; command -v gtk3-widget-factory || echo "NOT ON PATH"
echo; echo "== display env =="; echo "WAYLAND_DISPLAY=${WAYLAND_DISPLAY:-<unset>}  DISPLAY=${DISPLAY:-<unset>}  XDG_RUNTIME_DIR=${XDG_RUNTIME_DIR:-<unset>}"
echo; echo "== try a direct detached launch, capture stderr =="; setsid -f gtk3-widget-factory 2>/tmp/wf.err; sleep 1; pgrep -x gtk3-widget-fac && echo "LAUNCHED OK" || { echo "FAILED — stderr:"; cat /tmp/wf.err; }
